var data string
var done bool

go func() {
    data = "готово"
    done = true
}()

for !done { }       // может крутиться вечно
fmt.Println(data)   // может напечатать ""

// Правильно: синхронизация создаёт happens-before
var ready atomic.Bool
go func() {
    data = "готово"
    ready.Store(true)     // запись data «случилась до» Store
}()
for !ready.Load() { runtime.Gosched() }
fmt.Println(data)         // гарантированно "готово"
